/// $INTERFACE MCS_PDMA_REG                             (4,4)
///     # # ----------------------------------------------------------
///     @ 0x00000 DMA_CTRL_NS          (P)
///               ###
///               * DMA-250 Non-Secure System Controls
///               ###
///               %unsigned 1  allch_stop_req_nonsec     0x0
///                                    ###
///                                    * All channel stop request for Non-secure channels. When asserted,
///                                    * all Non-secure channels that are not in IDLE will be stopped.
///                                    * Channels can be enabled by SW, but will be immediately stopped
///                                    * if this request is asserted.
///                                    ###
///               %unsigned 1  allch_pause_req_nonsec    0x0
///                                    ###
///                                    * All channel pause request for Non-secure channels. When
///                                    * asserted, then all Non-secure channels that are not in IDLE
///                                    * will be paused. Channels can be enabled by SW, but will be
///                                    * immediately paused if this request is asserted. When the
///                                    * request is deasserted, the operation continues.
///                                    ###
///               %%        30         # Stuffing bits...
///     @ 0x00004 DMA_CTRL_S           (P)
///               ###
///               * DMA-250 Secure System Secure Controls
///               * Note: All DMA*_S registers are only accessible by secure
///               * managers. Non-secure managers will RAZ/WI
///               ###
///               %unsigned 1  allch_stop_req_sec        0x0
///                                    ###
///                                    * All channel stop request for Secure channels. When asserted, all
///                                    * Secure channels that are not in IDLE will be stopped. Channels
///                                    * can be enabled by SW, but will be immediately stopped if this
///                                    * request is asserted.
///                                    ###
///               %unsigned 1  allch_pause_req_sec       0x0
///               %%        30         # Stuffing bits...
///     @ 0x00008 DMA_STAT_0_NS        (R-)
///               ###
///               * DMA-250 System Non-Secure Status
///               ###
///               %unsigned 1  allch_stop_ack_nonsec     
///                                    ###
///                                    * All channel stopped acknowledge for Non-secure channels. When
///                                    * asserted, all Non-secure channels are stopped or inactive.
///                                    * Four-phase handshake pair of allch_stop_req_nonsec.
///                                    ###
///               %unsigned 1  allch_pause_ack_nonsec    
///                                    ###
///                                    * All channel pause acknowledge for Non-secure channels. When
///                                    * asserted, all Non-secure channels are paused or inactive.
///                                    * Four-phase handshake pair of allch_pause_req_nonsec.
///                                    ###
///               %%        30         # Stuffing bits...
///     @ 0x0000C DMA_STAT_0_S         (R-)
///               ###
///               * DMA-350 System Secure Status
///               ###
///               %unsigned 1  allch_stop_ack_sec        
///                                    ###
///                                    * All channel stopped acknowledge for Secure channels. When
///                                    * asserted, all Secure channels are stopped or inactive.
///                                    * Four-phase handshake pair of allch_stop_req_sec.
///                                    ###
///               %unsigned 1  allch_pause_ack_sec       
///                                    ###
///                                    * All channel pause acknowledge for Secure channels. When
///                                    * asserted, all Secure channels are paused or inactive.
///                                    * Four-phase handshake pair of allch_pause_req_sec.
///                                    ###
///               %%        30         # Stuffing bits...
///     @ 0x00010 DMA_STAT_1_NS        (R-)
///               ###
///               * DMA-350 System Non-Secure Status
///               ###
///               %unsigned 32 ch_enabled_nonsec         
///                                    ###
///                                    * Status indication per channel to show when a channel is active.
///                                    * Signals are ANDed with ch_nonsec
///                                    ###
///     # 0x00014 DMA_STAT_1_NS1       
///               %unsigned 32 ch_err_nonsec             
///                                    ###
///                                    * Status indication per channel to show when a channel has
///                                    * encountered an error.
///                                    * Signals are ANDed with ch_nonsec
///                                    ###
///     # 0x00018 DMA_STAT_1_NS2       
///               %unsigned 32 ch_stopped_nonsec         
///                                    ###
///                                    * Status indication per channel to show when a channel is stopped.
///                                    * Signals are ANDed with ch_nonsec
///                                    ###
///     # 0x0001C DMA_STAT_1_NS3       
///               %unsigned 32 ch_paused_nonsec          
///                                    ###
///                                    * Status indication per channel to show when a channel is paused.
///                                    * Signals are ANDed with ch_nonsec
///                                    ###
///     @ 0x00020 DMA_STAT_1_S         (R-)
///               ###
///               * DMA-350 System Secure Status
///               ###
///               %unsigned 32 ch_enabled_sec            
///                                    ###
///                                    * Status indication per channel to show when a channel is active.
///                                    * Signals are ANDed with !ch_nonsec
///                                    ###
///     # 0x00024 DMA_STAT_1_S1        
///               %unsigned 32 ch_err_sec                
///                                    ###
///                                    * Status indication per channel to show when a channel has
///                                    * encountered an error.
///                                    * Signals are ANDed with !ch_nonsec
///                                    ###
///     # 0x00028 DMA_STAT_1_S2        
///               %unsigned 32 ch_stopped_sec            
///                                    ###
///                                    * Status indication per channel to show when a channel is stopped.
///                                    * Signals are ANDed with !ch_nonsec
///                                    ###
///     # 0x0002C DMA_STAT_1_S3        
///               %unsigned 32 ch_paused_sec             
///                                    ###
///                                    * Status indication per channel to show when a channel is paused.
///                                    * Signals are ANDed with !ch_nonsec
///                                    ###
///     @ 0x00030 DMA_STAT_2_NS        (R-)
///               ###
///               * DMA-350 System Non Secure Status
///               ###
///               %unsigned 32 ch_priv_nonsec            
///                                    ###
///                                    * Status indication per channel to show the privilege setting of
///                                    * the channel.
///                                    * Signals are ANDed with ch_nonsec
///                                    ###
///     @ 0x00034 DMA_STAT_2_S         (R-)
///               ###
///               * DMA-350 System Secure Status
///               ###
///               %unsigned 32 ch_priv_sec               
///                                    ###
///                                    * Status indication per channel to show the privilege setting of
///                                    * the channel.
///                                    * Signals are ANDed with !ch_nonsec
///                                    ###
///     # 0x00038 DMA_STAT_2_S1        
///               %unsigned 32 ch_nonsec                 
///                                    ###
///                                    * Status indication per channel to show the security setting of
///                                    * the channel.
///                                    ###
///     @ 0x0003C DMA_BOOT_0_S         (P)
///               ###
///               * DMA-350 System Boot Configuration
///               ###
///               %unsigned 1  boot_en                   0x0
///                                    ###
///                                    * Enables the channel 0 to load a first command after reset from a
///                                    * specified input address set by boot_addr
///                                    ###
///               %unsigned 8  boot_memattr              0x0
///                                    ###
///                                    * Boot address memory attributes. Has the same encodings as the
///                                    * LINKMEMATTRHI and LINKMEMATTRLO registers combined
///                                    ###
///               %unsigned 2  boot_shareattr            0x0
///                                    ###
///                                    * Boot address shareability attributes. Has the same encoding as
///                                    * the LINKSHAREATTR register
///                                    ###
///               %unsigned 1  boot_priv                 
///                                    ###
///                                    * Privilege status setting for channel 0. Sampled once after reset
///                                    * when power and clock have become stable and boot_en is HIGH
///                                    ###
///               %%        20         # Stuffing bits...
///     @ 0x00040 DMA_BOOT_1_S         (P)
///               ###
///               * DMA-350 System Boot Configuration
///               ###
///               %unsigned 30 boot_addr                 0x0
///                                    ###
///                                    * Word-aligned address for the boot process. boot_addr must point
///                                    * to a secure memory region because channel 0 boots as secure
///                                    * Maps to boot_addr[32:2]
///                                    ###
///               %%        2          # Stuffing bits...
///     @ 0x00044 DMA_CLK_CTRL         (P)
///               ###
///               * DMA-350 Q-Channel Control
///               ###
///               %unsigned 1  clk_force                 0x0
///                                    ###
///                                    * Setting to 1 disables dynamic clock gating on the q-channel
///                                    ###
///               %unsigned 8  entry_delay               0x0
///                                    ###
///                                    * Sets the value of the quiescence entry delay. Adds 0-255 clk
///                                    * cycles of hysteresis to the quiescence entry sequence
///                                    ###
///               %%        23         # Stuffing bits...
///     @ 0x00048 DMA_CTX_CTRL0        (P)
///               %unsigned 20 initial_cntxbase          0x0
///                                    ###
///                                    * 4-KB aligned context area base pointer that will be sampled to
///                                    * SEC_CNTXBASE. Sampled once after reset when power and clock
///                                    * have become stable
///                                    ###
///               %%        12         # Stuffing bits...
///     @ 0x0004C DMA_CTX_CTRL1        (P)
///               %unsigned 1  Initial_cntxmem_clr       0x0
///                                    ###
///                                    * Enables context memory initialization after reset. Sampled once
///                                    * after reset when power and clock have become stable
///                                    ###
///               %%        31         # Stuffing bits...
///     # # ----------------------------------------------------------
