/// $INTERFACE MCS_REG                 biu              (4,4)
///     ###
///     * CSR Registers to Control Blocks in Main SOC
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000                      (P)
///     # 0x00000 SDMA                 
///               $MCS_DMA_REG         SDMA              REG          
///     @ 0x0002C                      (P)
///     # 0x0002C PDMA                 
///               $MCS_PDMA_REG        PDMA              REG          
///     @ 0x0007C CPU_CTRL0            (P)
