///                                    * Non-secure SysTick calibration configuration:
///                                    * [23:0] TENMS
///                                    * [24] SKEW
///                                    * [25] NOREF
///                                    * Refer to Arm Cortex-M52 TRM for further details.
///                                    ###
///               %%        6          # Stuffing bits...
///     @ 0x00088 CPU_CTRL3            (P)
///               %unsigned 1  locknsvtor                0x0
///                                    ###
///                                    * When set to HIGH, writes to VTOR_NS is disabled.
///                                    * Once set to HIGH, it cannot be cleared until RESET
///                                    ###
///               %unsigned 1  locknsmpu                 0x0
///                                    ###
///                                    * When set to HIGH, writes to registers associated with the
///                                    * Non-Secure Memory Protection Unit (MPU) region are disabled
///                                    * Once set to HIGH, it cannot be cleared until RESET
///                                    ###
///               %%        30         # Stuffing bits...
///     @ 0x0008C                      (P)
///     # 0x0008C SPROT_MBOX           
///               $MCS_INTF_LOCK       SPROT_MBOX        REG          
///     @ 0x0009C                      (P)
///     # 0x0009C APP_CRYPTO           
///               $MCS_INTF_LOCK       APP_CRYPTO        REG          
///                                    ###
///                                    * Locks both APP_CRYPTO and APP_CRYPTO_RKEK on their register
///                                    * interface
///                                    ###
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:     172B, bits:     590b, padding:     0B
