//////
/// 
/// $INTERFACE MCS_SEC_REG             biu              (4,4)
///     ###
///     * These registers are behind a PPC. Software is expected to set it
///     * to secure and privileged only
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 SECRESP_CTRL         (P)
///               %unsigned 1  cfg_sec_resp              0x0
///                                    ###
///                                    * Connects to MSCs and PPCs. Configures how the subordinate
///                                    * responds to an access that violates the security permissions:
///                                    * 0: RAZ/WI
///                                    * 1: Bus error
///                                    ###
///               %%        31         # Stuffing bits...
///     @ 0x00004 PPC_AP_0             (P)
///               %unsigned 32 cfg_ap                    0x0
///                                    ###
///                                    * Connected to cfg_ap of PPCs to define the privileged access
///                                    * rights of subordinates.
///                                    * 0: Non-privileged access not allowed
///                                    * 1: Non-privileged access allowed
///                                    ###
///     @ 0x00008 PPC_NS_0             (P)
///               %unsigned 32 cfg_nonsec                0x0
///                                    ###
///                                    * Connected to cfg_nonsec of PPCs to define the secure access
///                                    * rights of subordinates
///                                    * 0: Only secure access allowed
///                                    * 1: Only non-Secure allowed
///                                    ###
///     @ 0x0000C PPC_AP_1             (P)
///               %unsigned 32 cfg_ap                    0x0
///                                    ###
///                                    * Connected to cfg_ap of PPCs to define the privileged access
///                                    * rights of subordinates.
///                                    * 0: Non-privileged access not allowed
///                                    * 1: Non-privileged access allowed
///                                    ###
///     @ 0x00010 PPC_NS_1             (P)
///               %unsigned 32 cfg_nonsec                0x0
///                                    ###
///                                    * Connected to cfg_nonsec of PPCs to define the secure access
///                                    * rights of subordinates
///                                    * 0: Only secure access allowed
///                                    * 1: Only non-Secure allowed
///                                    ###
///     @ 0x00014 PPC_AP_2             (P)
///               %unsigned 32 cfg_ap                    0x0
///                                    ###
///                                    * Connected to cfg_ap of PPCs to define the privileged access
///                                    * rights of subordinates.
///                                    * 0: Non-privileged access not allowed
///                                    * 1: Non-privileged access allowed
///                                    ###
///     @ 0x00018 PPC_NS_2             (P)
///               %unsigned 32 cfg_nonsec                0x0
///                                    ###
///                                    * Connected to cfg_nonsec of PPCs to define the secure access
///                                    * rights of subordinates
///                                    * 0: Only secure access allowed
///                                    * 1: Only non-Secure allowed
///                                    ###
///     @ 0x0001C PPC_INT_EN           (P)
///               %unsigned 16 irq_enable                0x0
///                                    ###
///                                    * Each bit controls the irq_enable of a specific PPC in the system
///                                    ###
///               %%        16         # Stuffing bits...
///     @ 0x00020 PPC_INT_CLR          (P)
///               %unsigned 16 irq_clear                 0x0
///                                    ###
///                                    * Each bit controls the irq_clear of a specific PPC in the system
///                                    ###
///               %%        16         # Stuffing bits...
///     @ 0x00024 PPC_INT_STAT         (R-)
///               %unsigned 16 irq_stat                  0x0
///                                    ###
///                                    * Each bit reflects the interrupt status of a specific PPC in the
///                                    * system
///                                    ###
///               %%        16         # Stuffing bits...
///     @ 0x00028 CPU_SEC_CTRL0        (RW-)
///               %unsigned 1  locksvtaircr              0x0
///                                    ###
///                                    * When set to HIGH, writes to VTOR_S, AIRCR.PRIS and
///                                    * AIRCR.BFHFNMINS are disabled.
///                                    * Once set to HIGH, it cannot be cleared until RESET
///                                    ###
///               %unsigned 1  locksau                   0x0
///                                    ###
///                                    * When set to HIGH, writes to registers associated with the SAU
///                                    * region are disabled
///                                    * Once set to HIGH, it cannot be cleared until RESET
///                                    ###
///               %unsigned 1  locksmpu                  0x0
///                                    ###
///                                    * When set to HIGH, writes to registers associated with the Secure
///                                    * Memory Protection Unit (MPU) region are disabled
///                                    * Once set to HIGH, it cannot be cleared until RESET
///                                    ###
///               %unsigned 1  locktcm                   0x0
///                                    ###
///                                    * When set to HIGH, writes to registers associated with the TCM
///                                    * region, ITCMCR and DTCMCR are disabled.
///                                    * Once set to HIGH, it cannot be cleared until RESET
///                                    ###
///               %unsigned 1  lockitgu                  0x0
///                                    ###
///                                    * When set to HIGH, writes to registers associated with ITCM
///                                    * interface security gating, ITGUCTRL and ITGU_LUTn are disabled.
///                                    * Once set to HIGH, it cannot be cleared until RESET
///                                    ###
///               %unsigned 1  lockdtgu                  0x0
///                                    ###
///                                    * When set to HIGH, writes to registers associated with DTCM
///                                    * interface security gating, DTGUCTRL and DTGU_LUTn are disabled.
///                                    * Once set to HIGH, it cannot be cleared until RESET
///                                    ###
///               %%        26         # Stuffing bits...
///     @ 0x0002C CPU_SEC_CTRL1        (RW-)
///               %unsigned 1  initsvtorlock             0x0
///                                    ###
///                                    * Lock initsvtor. When set to 1, further writes to initsvtorlock
///                                    * and initsvtor fields are disabled.
///                                    ###
///               %unsigned 6  reserved                  0x0
///               %unsigned 25 initsvtor                 0x220000
///                                    ###
///                                    * Secure vector table offset out of reset.
///                                    * Note: Set to 0x1100_0000 upon reset.
///                                    ###
///     @ 0x00030 CPU_SEC_CTRL2        (P)
///               %unsigned 26 cfgsstcalib               0x0
///                                    ###
///                                    * Secure SysTick calibration configuration:
///                                    * [23:0] TENMS
///                                    * [24] SKEW
///                                    * [25] NOREF
///                                    * Refer to Arm Cortex-M52 TRM for further details.
///                                    ###
///               %%        6          # Stuffing bits...
///     @ 0x00034 CPU_SEC_CTRL3        (P)
///               %unsigned 1  cpuwait                   0x1
///                                    ###
///                                    * The core is stalled out of reset when set to 1.
///                                    ###
///               %%        31         # Stuffing bits...
///     @ 0x00038 CPU_SEC_CTRL4        (P)
///               %unsigned 3  cfgmemalias               0x4
///                                    ###
///                                    * Memory address alias bit for ITCM, DTCM, and P-AHB regions. The
///                                    * address bit used for memory alias is determined by:
///                                    * 3’b001: Alias bit = 26
///                                    * 3’b010: Alias bit = 27
///                                    * 3’b100: Alias bit = 28
///                                    * 3’b000: No alias. TCM security gating is disabled.
///                                    * All other values will result in unpredictable behavior.
///                                    ###
///               %%        29         # Stuffing bits...
///     @ 0x0003C MSC_CFG_NS           (P)
///               %unsigned 16 cfg_nonsec                0x0
///                                    ###
///                                    * Each bit controls the cfg_nonsec input of a specific MSC in the
///                                    * system
///                                    ###
///               %%        16         # Stuffing bits...
///     @ 0x00040 MSC_INT_EN           (P)
///               %unsigned 16 irq_enable                0x0
///                                    ###
///                                    * Each bit controls the irq_enable of a specific MSC in the system
///                                    ###
///               %%        16         # Stuffing bits...
///     @ 0x00044 MSC_INT_CLR          (P)
///               %unsigned 16 irq_clear                 0x0
///                                    ###
///                                    * Each bit controls the irq_clear of a specific MSC in the system
///                                    ###
///               %%        16         # Stuffing bits...
///     @ 0x00048 MSC_INT_STAT         (R-)
///               %unsigned 16 irq_stat                  0x0
///                                    ###
///                                    * Each bit reflects the interrupt status of a specific MSC in the
///                                    * system
///                                    * Regions to offset the address sent to out the AXI manager
///                                    * interface towards the SOC.
///                                    * If regions overlap, the lower index region wins.
///                                    ###
///               %%        16         # Stuffing bits...
///     @ 0x0004C                      (P)
///     # 0x0004C SOC_INTF_REGION0     
///               $MCS_SOC_INTF        SOC_INTF_REGION0  REG          
///     @ 0x0005C                      (P)
///     # 0x0005C SOC_INTF_REGION1     
///               $MCS_SOC_INTF        SOC_INTF_REGION1  REG          
///     @ 0x0006C                      (P)
///     # 0x0006C SOC_INTF_REGION2     
///               $MCS_SOC_INTF        SOC_INTF_REGION2  REG          
